// fayl: app/Tabs.tsx
"use client"
import { useState } from "react"

export function Tabs({ panels }: { panels: Record<string, React.ReactNode> }) {
  const names = Object.keys(panels)
  const [active, setActive] = useState(names[0])
  return (
    <div>
      {names.map((n) => (
        <span key={n}>
          <button onClick={() => setActive(n)}>{n === active ? `[${n}]` : n}</button>{" "}
        </span>
      ))}
      {panels[active]}
    </div>
  )
}

