// fayl: app/actions.ts
"use server"

export type State = { error?: string; ok?: string }

export async function register(_prev: State, formData: FormData): Promise<State> {
  const phone = String(formData.get("phone"))
  if (!/^[+]998[0-9]{9}$/.test(phone)) return { error: "Telefon +998XXXXXXXXX formatida bo'lsin" }
  return { ok: `✓ ${phone} ro'yxatdan o'tdi` }
}

