// fayl: app/Bars.tsx
"use client"
import { useState } from "react"

export function Bars({ data }: { data: [string, number][] }) {
  const [hover, setHover] = useState<string | null>(null)
  const max = Math.max(...data.map(([, v]) => v))
  return (
    <div>
      {data.map(([k, v]) => (
        <p key={k} onMouseEnter={() => setHover(k)}>{k.padEnd(9, " ")} {"█".repeat(Math.round((v / max) * 10))}</p>
      ))}
      <p>{hover ? `${hover}: ${data.find(([k]) => k === hover)![1]} ta` : "Ustiga olib boring"}</p>
    </div>
  )
}

