"use server"

const all = Array.from({ length: 7 }, (_, i) => `Retsept ${i + 1}`)

export async function loadMore(offset: number) {
  return { items: all.slice(offset, offset + 3), hasMore: offset + 3 < all.length }
}

// fayl: app/Feed.tsx
"use client"
import { useState } from "react"
import { loadMore } from "./actions"

export function Feed({ initial }: { initial: string[] }) {
  const [items, setItems] = useState(initial)
  const [hasMore, setHasMore] = useState(true)
  const more = async () => {
    const r = await loadMore(items.length)
    setItems([...items, ...r.items])
    setHasMore(r.hasMore)
  }
  return (
    <div>
      <p>{items.join(", ")}</p>
      {hasMore && <button onClick={more}>Ko'proq</button>}
    </div>
  )
}

